import * as tp from 'node:timers/promises';
function t(f: () => any): Promise<void> {
  return Promise.resolve().then(() => { const r: any = f(); return r && typeof r.next === 'function' ? r.next() : r; }).then(() => { console.log('ok'); }, (e: any) => { console.log(e.name, e.code, e.message); });
}
async function main(): Promise<void> {
  const m: any = tp;
  await t(() => m.setTimeout('x'));
  await t(() => m.setTimeout(null, 1));
  await t(() => m.setTimeout(1, 1, 5));
  await t(() => m.setTimeout(1, 1, null));
  await t(() => m.setTimeout(1, 1, { signal: 5 }));
  await t(() => m.setTimeout(1, 1, { ref: 'a' }));
  await t(() => m.setImmediate(1, 5));
  await t(() => m.setImmediate(1, { signal: {} }));
  await t(() => m.setImmediate(1, { ref: 1 }));
  await t(() => m.setInterval('x'));
  await t(() => m.setInterval(1, 1, 5));
  await t(() => m.setInterval(1, 1, { signal: 5 }));
  await t(() => m.scheduler.wait('x'));
  await t(() => m.scheduler.wait(1, 5));
  await t(() => m.scheduler.yield());
}
